<?php require 'header.php';role_required(['ADMIN','WAREHOUSE']);$products=$pdo->query('SELECT product_id,sku,product_name,unit FROM products WHERE is_active=1 ORDER BY product_name')->fetchAll();$locations=$pdo->query('SELECT l.location_id,CONCAT(w.warehouse_name," • ",l.bin_code) label FROM storage_locations l JOIN warehouses w ON w.warehouse_id=l.warehouse_id ORDER BY l.bin_code')->fetchAll();$err='';if($_SERVER['REQUEST_METHOD']==='POST'){$qty=(float)$_POST['qty'];$in=$_POST['type']==='IN';if($qty<=0)$err='Jumlah harus lebih dari nol.';else{$pdo->beginTransaction();try{$pdo->prepare('INSERT INTO stock_balances(product_id,location_id,qty_on_hand) VALUES(?,?,?) ON DUPLICATE KEY UPDATE qty_on_hand=qty_on_hand+VALUES(qty_on_hand)')->execute([$_POST['product'],$_POST['location'],$in?$qty:-$qty]);$c=$pdo->prepare('SELECT qty_on_hand FROM stock_balances WHERE product_id=? AND location_id=?');$c->execute([$_POST['product'],$_POST['location']]);if($c->fetchColumn()<0)throw new Exception('Stok pada lokasi yang dipilih tidak mencukupi.');$no='TRX-'.date('YmdHis').'-'.random_int(100,999);$pdo->prepare('INSERT INTO stock_transactions(transaction_number,product_id,from_location_id,to_location_id,transaction_type,quantity,reference_no,notes) VALUES(?,?,?,?,?,?,?,?)')->execute([$no,$_POST['product'],$in?null:$_POST['location'],$in?$_POST['location']:null,$in?'PURCHASE_RECEIPT':'SALES_ISSUE',$qty,trim($_POST['reference']),trim($_POST['notes'])]);$pdo->commit();flash("Transaksi $no berhasil disimpan.");header('Location:transactions.php');exit;}catch(Throwable $e){$pdo->rollBack();$err=$e->getMessage();}}}$recent=$pdo->query('SELECT t.transaction_number,t.transaction_type,t.quantity,t.transaction_date,p.product_name FROM stock_transactions t JOIN products p ON p.product_id=t.product_id ORDER BY t.transaction_id DESC LIMIT 7')->fetchAll();?><div class="page-intro"><div><h2>Transaksi stok</h2><p>Catat pergerakan material dan produk di lokasi gudang.</p></div><span class="role-note">Warehouse access</span></div><?php if($err):?><div class="alert error">! <?=e($err)?></div><?php endif?><div class="two-col"><section class="panel form-panel"><div class="panel-head"><div><h3>Input transaksi</h3><p>Stok akan diperbarui setelah data disimpan.</p></div></div><form method="post" class="form-grid"><label>Jenis transaksi<select name="type"><option value="IN">↓ Barang masuk</option><option value="OUT">↑ Barang keluar</option></select></label><label>Barang<select name="product"><?php foreach($products as $p):?><option value="<?=$p['product_id']?>"><?=e($p['sku'].' — '.$p['product_name'])?></option><?php endforeach?></select></label><label>Lokasi penyimpanan<select name="location"><?php foreach($locations as $l):?><option value="<?=$l['location_id']?>"><?=e($l['label'])?></option><?php endforeach?></select></label><label>Jumlah<input type="number" name="qty" min="0.01" step="0.01" placeholder="0" required></label><label>Nomor referensi<input name="reference" placeholder="PO / SO / DO / PRD"></label><label>Catatan<input name="notes" placeholder="Keterangan transaksi"></label><div class="form-action"><button class="primary">Simpan transaksi →</button></div></form></section><section class="panel list-panel"><div class="panel-head"><div><h3>Transaksi terakhir</h3><p>7 aktivitas stok terbaru</p></div></div><?php foreach($recent as $r):?><div class="activity"><div class="activity-icon <?=$r['transaction_type']==='SALES_ISSUE'?'out':'in'?>"><?=$r['transaction_type']==='SALES_ISSUE'?'↑':'↓'?></div><div><b><?=e($r['product_name'])?></b><small><?=e($r['transaction_number'].' • '.date('d M Y H:i',strtotime($r['transaction_date'])))?></small></div><div class="activity-value <?=$r['transaction_type']==='SALES_ISSUE'?'minus':'plus'?>"><?=$r['transaction_type']==='SALES_ISSUE'?'-':'+'?><?=e($r['quantity'])?></div></div><?php endforeach;if(!$recent):?><p class="empty">Belum ada transaksi.</p><?php endif?></section></div><?php require 'footer.php';?>